import csv, json
from pathlib import Path

tsv_path = Path('Answers/results/reaults.tsv')
json_path = Path('Answers/results/0621_sun_1210.json')

# email -> column-prefix
pref = {
    'atar_a@webiks.com': 'A',
    'daniellehuy@gmail.com': 'D',
    'nitzan.gour@gmail.com': 'Z',
    'noga_ca@webiks.com': 'G',
}
score_map = {
    'score_coherence': 'ch',
    'score_relevance': 'rl',
    'score_completeness': 'cm',
    'score_faithfulness': 'ft',
    'score_attribution': 'at',
}
text_map = {
    'annotator_review': 'rwnote',
    'annotator_note': 'note',
    'annotator_rephrasing': 'rephrasing',
}

with tsv_path.open('r', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f, delimiter='\t')
    rows = list(reader)
    fieldnames = reader.fieldnames

by_task = {}
for i, r in enumerate(rows):
    url = r.get('ls_task_url','')
    if 'task=' in url:
        task = int(url.rsplit('task=',1)[1])
        by_task[task] = i

snapshot = json.loads(json_path.read_text(encoding='utf-8'))

updated = 0
cells_changed = 0
for task in snapshot:
    task_id = task.get('id')
    if task_id not in by_task:
        continue
    row = rows[by_task[task_id]]

    # keep most recent valid annotation per email
    latest = {}
    for ann in task.get('annotations', []):
        if ann.get('was_cancelled'):
            continue
        cb = ann.get('completed_by') or {}
        email = (cb.get('email') or '').strip().lower()
        if email not in pref:
            continue
        stamp = ann.get('updated_at') or ann.get('created_at') or ''
        cur = latest.get(email)
        if cur is None or stamp > cur[0]:
            latest[email] = (stamp, ann)

    before = dict(row)

    for email, (_, ann) in latest.items():
        p = pref[email]
        values = {}
        for res in ann.get('result', []):
            fn = res.get('from_name')
            val = res.get('value') or {}
            if fn in score_map:
                choices = val.get('choices') or []
                v = ''
                if choices:
                    c = str(choices[0]).strip().lower()
                    if c == 'reviewed':
                        v = 'v'
                    elif c in ('0','1','2'):
                        v = c
                    elif c:
                        v = str(choices[0])
                values[f'{p}_{score_map[fn]}'] = v
            elif fn == 'not-sensible':
                choices = val.get('choices') or []
                v = 'v' if choices and str(choices[0]).strip().lower() == 'reviewed' else ''
                values[f'{p}_rw'] = v
            elif fn in text_map:
                txt = val.get('text') or []
                values[f'{p}_{text_map[fn]}'] = '\n'.join(str(x) for x in txt).strip() if txt else ''

        for k, v in values.items():
            if k in row and row[k] != v:
                row[k] = v
                cells_changed += 1

    done = sum(1 for p in pref.values() if (row.get(f'{p}_rw') or '').strip().lower() == 'v')
    new_done = str(done * 25)
    if row.get('rw_done','') != new_done:
        row['rw_done'] = new_done
        cells_changed += 1

    if row != before:
        updated += 1

with tsv_path.open('w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames, delimiter='\t', lineterminator='\n')
    writer.writeheader()
    writer.writerows(rows)

print('rows_updated', updated)
print('cells_changed', cells_changed)
