from datetime import datetime

base = Path('Answers/results')
results_path = base / 'reaults.tsv'
pairs_path = base / 'results_qwk_pairs.tsv'
review_path = base / 'review_data.tsv'
out_path = base / 'iaa_report.html'

metrics = ['ch', 'rl', 'cm', 'ft']
metric_labels = {
    'ch': 'Coherence',
    'rl': 'Relevance',
    'cm': 'Completeness',
    'ft': 'Faithfulness',
}
raters = ['A', 'D', 'Z', 'G']
pairs = [('A', 'D'), ('A', 'Z'), ('A', 'G'), ('D', 'Z'), ('D', 'G'), ('Z', 'G')]

with results_path.open('r', encoding='utf-8', newline='') as f:
    results_rows = list(csv.DictReader(f, delimiter='\t'))
with pairs_path.open('r', encoding='utf-8', newline='') as f:
    pairs_rows = list(csv.DictReader(f, delimiter='\t'))
with review_path.open('r', encoding='utf-8', newline='') as f:
    review_rows = list(csv.DictReader(f, delimiter='\t'))

if not pairs_rows:
    raise RuntimeError('results_qwk_pairs.tsv is empty')

pairs_row = pairs_rows[0]
overall_qwk = {m: float(pairs_row[f'QWK_{m}']) for m in metrics}

heatmaps = {}
for m in metrics:
    mat = {r: {c: (1.0 if r == c else None) for c in raters} for r in raters}
    for a, b in pairs:
        v = float(pairs_row[f'{a}-{b}_{m}'])
        mat[a][b] = v
        mat[b][a] = v
    heatmaps[m] = mat

review_summary = {}
for r in raters:
    col = f'{r}_rw'
    reviewed = 0
    not_reviewed = 0
    for row in review_rows:
        if (row.get(col) or '').strip().lower() == 'v':
            reviewed += 1
        else:
            not_reviewed += 1
    review_summary[r] = {'reviewed': reviewed, 'not_reviewed': not_reviewed}


def parse_score(v):
    v = (v or '').strip()
    return int(v) if v in {'0', '1', '2'} else None


disagreement_rows = []
rows_with_any_disagreement = 0
rows_with_full_agreement = 0

for row in results_rows:
    disagree_metrics = []
    metric_details = []
    for m in metrics:
        vals = {r: parse_score(row.get(f'{r}_{m}')) for r in raters}
        valid_vals = [v for v in vals.values() if v is not None]
        if len(valid_vals) >= 2 and len(set(valid_vals)) > 1:
            disagree_metrics.append(m)
            metric_details.append(
                f"{metric_labels[m]}: " + ', '.join(f"{r}={vals[r]}" for r in raters)
            )

    if disagree_metrics:
        rows_with_any_disagreement += 1
        disagreement_rows.append({
            'record_id': row.get('record_id', ''),
            'question': row.get('question', ''),
            'ls_task_url': row.get('ls_task_url', ''),
            'disagree_count': len(disagree_metrics),
            'metrics': ', '.join(metric_labels[m] for m in disagree_metrics),
            'details': ' | '.join(metric_details),
        })
    else:
        rows_with_full_agreement += 1


disagreement_rows.sort(key=lambda x: (-x['disagree_count'], x['record_id']))
TOP_N = 40
top_disagreements = disagreement_rows[:TOP_N]


def cell_color(v):
    lo, hi = -0.1, 1.0
    v = max(lo, min(hi, v))
    t = (v - lo) / (hi - lo)
    r1, g1, b1 = 248, 215, 218
    r2, g2, b2 = 212, 237, 218
    r = int(r1 + (r2 - r1) * t)
    g = int(g1 + (g2 - g1) * t)
    b = int(b1 + (b2 - b1) * t)
    return f'rgb({r},{g},{b})'


heatmap_html_parts = []
for m in metrics:
    mat = heatmaps[m]
    rows_html = []
    header = ''.join(f'<th>{r}</th>' for r in raters)
    for r in raters:
        tds = []
        for c in raters:
            v = mat[r][c]
            bg = cell_color(v)
            tds.append(f'<td style="background:{bg};">{v:.3f}</td>')
        rows_html.append(f'<tr><th>{r}</th>{"".join(tds)}</tr>')

    heatmap_html_parts.append(f'''
    <div class="heatmap-card">
      <h4>{metric_labels[m]}</h4>
      <table class="heatmap-table">
        <thead><tr><th></th>{header}</tr></thead>
        <tbody>
          {''.join(rows_html)}
        </tbody>
      </table>
    </div>
    ''')

rows_html = []
for d in top_disagreements:
    rid = html.escape(d['record_id'])
    url = (d.get('ls_task_url') or '').strip()
    if url:
        rid_html = f'<a href="{html.escape(url, quote=True)}" target="_blank" rel="noopener">{rid}</a>'
    else:
        rid_html = rid

    rows_html.append(
        '<tr>'
        f'<td>{rid_html}</td>'
        f'<td>{d["disagree_count"]}</td>'
        f'<td>{html.escape(d["metrics"])}</td>'
        f'<td>{html.escape(d["question"])}</td>'
        f'<td>{html.escape(d["details"])}</td>'
        '</tr>'
    )

disagreement_table_html = ''.join(rows_html)

overall_chart_data = {
    'labels': [metric_labels[m] for m in metrics],
    'values': [overall_qwk[m] for m in metrics],
}
review_chart_data = {
    'labels': raters,
    'reviewed': [review_summary[r]['reviewed'] for r in raters],
    'not_reviewed': [review_summary[r]['not_reviewed'] for r in raters],
}

generated_at = datetime.now().strftime('%Y-%m-%d %H:%M')

html_doc = f'''<!doctype html>
